/*
 * Syscall groups selectable through Kconfig (LIBVMITRACE_GROUP_*).
 *
 * Each list is an X-macro X(name, a) over SYS_* names from <uk/bits/syscall_nrs.h>
 * (generated by syscall_shim from the Linux x86_64 table), so a misspelt
 * name fails the build instead of silently tracing nothing. `a` is passed
 * through unchanged (vmitrace.c uses it for the bitmap word index).
 *
 * Groups are by syscall number only: read/write are in FILE even when the
 * fd is a socket.
 */

#ifndef __VMITRACE_GROUPS_H__
#define __VMITRACE_GROUPS_H__

#define VMITRACE_GROUP_NET(X, a)						\
	X(socket, a) X(bind, a) X(listen, a) X(accept, a) X(accept4, a) X(connect, a)	\
	X(recvfrom, a) X(sendto, a) X(recvmsg, a) X(sendmsg, a)			\
	X(setsockopt, a) X(getsockopt, a) X(shutdown, a)				\
	X(getpeername, a) X(getsockname, a) X(socketpair, a)

#define VMITRACE_GROUP_FILE(X, a)						\
	X(read, a) X(write, a) X(open, a) X(openat, a) X(close, a)			\
	X(stat, a) X(fstat, a) X(lstat, a) X(newfstatat, a) X(statx, a)		\
	X(lseek, a) X(pread64, a) X(pwrite64, a) X(readv, a) X(writev, a)		\
	X(preadv, a) X(pwritev, a) X(sendfile, a)				\
	X(access, a) X(faccessat, a) X(getdents64, a) X(fcntl, a)			\
	X(dup, a) X(dup2, a) X(dup3, a)						\
	X(truncate, a) X(ftruncate, a) X(fsync, a) X(fdatasync, a)			\
	X(mkdir, a) X(mkdirat, a) X(rmdir, a) X(unlink, a) X(unlinkat, a)		\
	X(rename, a) X(renameat, a) X(readlink, a) X(readlinkat, a)			\
	X(chdir, a) X(fchdir, a) X(getcwd, a) X(chmod, a) X(fchmod, a) X(fchmodat, a)

#define VMITRACE_GROUP_TIME(X, a)						\
	X(time, a) X(gettimeofday, a) X(settimeofday, a)				\
	X(clock_gettime, a) X(clock_settime, a) X(clock_getres, a)		\
	X(clock_nanosleep, a) X(nanosleep, a)					\
	X(timerfd_create, a) X(timerfd_settime, a) X(timerfd_gettime, a)

#endif /* __VMITRACE_GROUPS_H__ */
